<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Str;
use App\Models\{Outlet,Category,Product,Inventory,Order,User,Setting};
class CommerceTest extends TestCase {
 use RefreshDatabase;
 private function fixture(): array {
 $o=Outlet::create(['name'=>'Dhaka','address'=>'Test outlet','phone'=>'01000000000']);$c=Category::create(['name'=>'Phones']);$p=Product::create(['name'=>'Test phone','sku'=>'TEST','brand'=>'Test','category_id'=>$c->id,'description'=>'Phone','image'=>'https://example.com/phone.png','active'=>true]);$i=Inventory::create(['product_id'=>$p->id,'outlet_id'=>$o->id,'price'=>1000,'compare_price'=>1200,'quantity'=>3]);Setting::create(['key'=>'delivery_fee','value'=>'120']);return [$o,$p,$i];
 }
 private function payload($o,$p):array{return ['idempotency_key'=>(string)Str::uuid(),'outlet_id'=>$o->id,'customer_name'=>'Test Buyer','phone'=>'01700000000','address'=>'Test address','fulfillment'=>'delivery','items'=>[['product_id'=>$p->id,'quantity'=>2]]];}
 public function test_storefront_and_admin_pages_render():void{$this->get('/')->assertOk();$this->get('/admin')->assertOk();}
 public function test_admin_api_is_protected():void{$this->getJson('/api/v1/admin/data')->assertForbidden();$user=User::factory()->create();$this->actingAs($user)->getJson('/api/v1/admin/data')->assertForbidden();}
 public function test_prices_are_outlet_specific():void{[$o,$p]=$this->fixture();$other=Outlet::create(['name'=>'Other','address'=>'Here','phone'=>'01000000000']);Inventory::create(['product_id'=>$p->id,'outlet_id'=>$other->id,'price'=>1500,'quantity'=>0]);$this->getJson('/api/v1/products?outlet_id='.$other->id)->assertOk()->assertJsonPath('data.0.price',1500)->assertJsonPath('data.0.quantity',0);}
 public function test_hidden_products_and_inactive_outlets_are_unavailable():void{[$o,$p]=$this->fixture();$p->update(['active'=>false]);$this->getJson('/api/v1/products?outlet_id='.$o->id)->assertJsonCount(0,'data');$this->getJson('/api/v1/products/'.$p->id)->assertNotFound();$o->update(['active'=>false]);$this->getJson('/api/v1/products?outlet_id='.$o->id)->assertNotFound();}
 public function test_order_calculates_total_and_decrements_stock():void{[$o,$p,$i]=$this->fixture();$d=$this->payload($o,$p);$d['total']=1;$this->postJson('/api/v1/orders',$d)->assertCreated()->assertJsonPath('total',2120);$this->assertEquals(1,$i->fresh()->quantity);$this->assertDatabaseHas('order_items',['unit_price'=>1000,'quantity'=>2]);}
 public function test_order_retry_does_not_reserve_twice():void{[$o,$p,$i]=$this->fixture();$d=$this->payload($o,$p);$a=$this->postJson('/api/v1/orders',$d)->assertCreated()->json('reference');$this->postJson('/api/v1/orders',$d)->assertOk()->assertJsonPath('reference',$a);$this->assertEquals(1,Order::count());$this->assertEquals(1,$i->fresh()->quantity);}
 public function test_insufficient_stock_is_rejected():void{[$o,$p,$i]=$this->fixture();$d=$this->payload($o,$p);$d['items'][0]['quantity']=4;$this->postJson('/api/v1/orders',$d)->assertUnprocessable();$this->assertEquals(3,$i->fresh()->quantity);$this->assertEquals(0,Order::count());}
 public function test_unavailable_second_line_rolls_back_first_line():void{[$o,$p,$i]=$this->fixture();$p2=Product::create(['name'=>'Other phone','sku'=>'OTHER','brand'=>'Test','category_id'=>$p->category_id,'description'=>'Test','image'=>'https://example.com/a.png']);$d=$this->payload($o,$p);$d['items'][]=['product_id'=>$p2->id,'quantity'=>1];$this->postJson('/api/v1/orders',$d)->assertUnprocessable();$this->assertEquals(3,$i->fresh()->quantity);}
 public function test_duplicate_order_lines_are_rejected():void{[$o,$p,$i]=$this->fixture();$d=$this->payload($o,$p);$d['items'][]=$d['items'][0];$this->postJson('/api/v1/orders',$d)->assertUnprocessable();$this->assertEquals(3,$i->fresh()->quantity);}
 public function test_pickup_has_no_delivery_fee():void{[$o,$p]=$this->fixture();$d=$this->payload($o,$p);$d['fulfillment']='pickup';$this->postJson('/api/v1/orders',$d)->assertCreated()->assertJsonPath('total',2000);}
 public function test_admin_updates_inventory_and_store_settings():void{[$o,$p,$i]=$this->fixture();$u=User::factory()->create();$u->forceFill(['is_admin'=>true])->save();$this->actingAs($u)->putJson('/api/v1/admin/inventories/'.$i->id,['product_id'=>$p->id,'outlet_id'=>$o->id,'price'=>1100,'compare_price'=>1300,'quantity'=>6])->assertOk();$this->getJson('/api/v1/products?outlet_id='.$o->id)->assertJsonPath('data.0.price',1100);$this->putJson('/api/v1/admin/settings',['store_name'=>'New name','phone'=>'01700000000','tagline'=>'Hello','announcement'=>'Welcome','delivery_fee'=>50])->assertOk();$this->getJson('/api/v1/storefront')->assertJsonPath('settings.store_name','New name');}
 public function test_cancellation_restores_stock_only_once():void{[$o,$p,$i]=$this->fixture();$this->postJson('/api/v1/orders',$this->payload($o,$p))->assertCreated();$u=User::factory()->create();$u->forceFill(['is_admin'=>true])->save();$id=Order::first()->id;$this->actingAs($u)->patchJson('/api/v1/admin/orders/'.$id,['status'=>'cancelled'])->assertOk();$this->assertEquals(3,$i->fresh()->quantity);$this->patchJson('/api/v1/admin/orders/'.$id,['status'=>'cancelled'])->assertUnprocessable();$this->assertEquals(3,$i->fresh()->quantity);}
 public function test_invalid_admin_login_is_rejected():void{$this->postJson('/api/v1/admin/login',['email'=>'nobody@example.com','password'=>'wrong'])->assertUnprocessable();}
}
